"""A* on an ASCII grid (stdlib only)."""

import heapq
from typing import Dict, List, Set, Tuple

Pos = Tuple[int, int]

MAP = """\
S--#-
-#-#-
-#---
-#-#-
---#G\
"""


def parse(grid_text: str):
    """Return (start, goal, walls, rows, cols). # = wall, everything else open."""
    lines = grid_text.splitlines()
    start = goal = None
    walls: Set[Pos] = set()
    for r, line in enumerate(lines):
        for c, ch in enumerate(line):
            if ch == "#":
                walls.add((r, c))
            elif ch == "S":
                start = (r, c)
            elif ch == "G":
                goal = (r, c)
    assert start is not None and goal is not None, "map must contain S and G"
    return start, goal, walls, len(lines), max(len(l) for l in lines)


def manhattan(a: Pos, b: Pos) -> int:
    return abs(a[0] - b[0]) + abs(a[1] - b[1])


def neighbors(p: Pos, walls: Set[Pos], rows: int, cols: int) -> List[Pos]:
    r, c = p
    result = []
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):  # 4-connected
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in walls:
            result.append((nr, nc))
    return result


def reconstruct(came_from: Dict[Pos, Pos], current: Pos) -> List[Pos]:
    path = [current]
    while current in came_from:
        current = came_from[current]
        path.append(current)
    path.reverse()
    return path


def a_star(start: Pos, goal: Pos, walls: Set[Pos], rows: int, cols: int):
    """Return (path, expanded_count). Expanded = nodes popped from the open set."""
    g_score: Dict[Pos, float] = {start: 0}
    open_set: List[Tuple[float, float, Pos]] = [(manhattan(start, goal), manhattan(start, goal), start)]
    came_from: Dict[Pos, Pos] = {}
    closed: Set[Pos] = set()
    expanded = 0

    while open_set:
        _, _, current = heapq.heappop(open_set)
        if current in closed:
            continue
        closed.add(current)
        expanded += 1
        if current == goal:
            return reconstruct(came_from, current), expanded
        for nb in neighbors(current, walls, rows, cols):
            tentative = g_score[current] + 1
            if tentative < g_score.get(nb, float("inf")):
                g_score[nb] = tentative
                came_from[nb] = current
                f = tentative + manhattan(nb, goal)
                heapq.heappush(open_set, (f, f, nb))  # tie-break on h
    raise ValueError("no path found")


def overlay_path(grid_text: str, path: List[Pos]) -> str:
    """Return the map with '*' on every path cell except S and G."""
    chars = [list(line) for line in grid_text.splitlines()]
    for r, c in path:
        if chars[r][c] not in ("S", "G"):
            chars[r][c] = "*"
    return "\n".join("".join(row) for row in chars)


if __name__ == "__main__":
    start, goal, walls, rows, cols = parse(MAP)
    path, expanded = a_star(start, goal, walls, rows, cols)
    print(f"Path ({len(path) - 1} moves, {expanded} nodes expanded):")
    print(overlay_path(MAP, path))

